from flask import Flask, request, jsonify
from typing import Dict, List

app = Flask(__name__)

# インメモリデータベース（シミュレーション）
users_db: Dict[int, Dict] = {}
next_id = 1

# CREATE: ユーザー作成
@app.route('/api/users', methods=['POST'])
def create_user():
    global next_id
    data = request.get_json()

    # バリデーション
    if not data or 'username' not in data or 'email' not in data:
        return jsonify({'error': 'username and email required'}), 400

    # 新規ユーザー作成
    user = {
        'id': next_id,
        'username': data['username'],
        'email': data['email']
    }
    users_db[next_id] = user
    next_id += 1

    return jsonify(user), 201

# READ: ユーザー一覧
@app.route('/api/users', methods=['GET'])
def list_users():
    users = list(users_db.values())
    return jsonify({'users': users, 'count': len(users)}), 200

# READ: ユーザー詳細
@app.route('/api/users/<int:user_id>', methods=['GET'])
def get_user(user_id):
    user = users_db.get(user_id)
    if not user:
        return jsonify({'error': 'User not found'}), 404
    return jsonify(user), 200

# UPDATE: ユーザー更新
@app.route('/api/users/<int:user_id>', methods=['PUT'])
def update_user(user_id):
    user = users_db.get(user_id)
    if not user:
        return jsonify({'error': 'User not found'}), 404

    data = request.get_json()
    if 'username' in data:
        user['username'] = data['username']
    if 'email' in data:
        user['email'] = data['email']

    return jsonify(user), 200

# DELETE: ユーザー削除
@app.route('/api/users/<int:user_id>', methods=['DELETE'])
def delete_user(user_id):
    if user_id not in users_db:
        return jsonify({'error': 'User not found'}), 404

    deleted_user = users_db.pop(user_id)
    return jsonify({'message': 'User deleted', 'user': deleted_user}), 200

if __name__ == '__main__':
    print("✅ Flask + Database API created!\n")
    print("📋 Endpoints:")
    print("  POST   /api/users       - Create user")
    print("  GET    /api/users       - List all users")
    print("  GET    /api/users/<id>  - Get user by ID")
    print("  PUT    /api/users/<id>  - Update user")
    print("  DELETE /api/users/<id>  - Delete user")
    print("\n📝 Note: 実際はSQLAlchemyでDB操作を行います")
    print("📝 Flask-SQLAlchemy を使うとさらに簡潔に書けます")
